mapper.select:
SELECT SCHEDULE_DATE, CX_BATCH_NO, BIG_ROLL_CODE, SUM(DAY_PLAN_QTY) DAY_PLAN_QTY, SUM(NIGHT_PLAN_QTY) NIGHT_PLAN_QTY, SUM(CX_CLASS1_PLAN) CX_CLASS1_PLAN, SUM(CX_CLASS2_PLAN) CX_CLASS2_PLAN, SUM(CX_CLASS3_PLAN) CX_CLASS3_PLAN, SUM(CX_CLASS4_PLAN) CX_CLASS4_PLAN, SUM(CX_CLASS5_PLAN) CX_CLASS5_PLAN, ORIGINAL_LINE_CODE, '0' DATA_SOURCE /* 成型来的排程数据来源默认自动排产 */ from( SELECT R.SCHEDULE_DATE, /*排产日期*/ R.CX_BATCH_NO, /*成型批次号*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ IFNULL(ROUND(SUM((IFNULL(R.CLASS3_PLAN_QTY, 0)) * (IFNULL(CI.TIRE_FABRIC_CRAFT1 * CI.TIRE_FABRIC_LENGTH1, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT2 * CI.TIRE_FABRIC_LENGTH2, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT3 * CI.TIRE_FABRIC_LENGTH3, 0)) / 1000 /1000 / #{breadth}), 6), 0) DAY_PLAN_QTY, /*中班计划量*/ IFNULL(ROUND(SUM((IFNULL(R.CLASS4_PLAN_QTY, 0)) * (IFNULL(CI.TIRE_FABRIC_CRAFT1 * CI.TIRE_FABRIC_LENGTH1, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT2 * CI.TIRE_FABRIC_LENGTH2, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT3 * CI.TIRE_FABRIC_LENGTH3, 0)) / 1000 /1000 / #{breadth}), 6), 0) NIGHT_PLAN_QTY, /*夜班计划量*/ IFNULL(CEILING(SUM(R.CLASS3_PLANNED_QTY * (IFNULL(CI.TIRE_FABRIC_CRAFT1 * CI.TIRE_FABRIC_LENGTH1, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT2 * CI.TIRE_FABRIC_LENGTH2, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT3 * CI.TIRE_FABRIC_LENGTH3, 0)) / 1000 / 1000 / #{breadth})), 0) CX_CLASS1_PLAN, IFNULL(CEILING(SUM(R.CLASS2_PLAN_QTY * (IFNULL(CI.TIRE_FABRIC_CRAFT1 * CI.TIRE_FABRIC_LENGTH1, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT2 * CI.TIRE_FABRIC_LENGTH2, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT3 * CI.TIRE_FABRIC_LENGTH3, 0)) / 1000 / 1000 / #{breadth})), 0) CX_CLASS2_PLAN, IFNULL(CEILING(SUM(R.CLASS3_PLAN_QTY * (IFNULL(CI.TIRE_FABRIC_CRAFT1 * CI.TIRE_FABRIC_LENGTH1, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT2 * CI.TIRE_FABRIC_LENGTH2, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT3 * CI.TIRE_FABRIC_LENGTH3, 0)) / 1000 / 1000 / #{breadth})), 0) CX_CLASS3_PLAN, IFNULL(CEILING(SUM(R.CLASS4_PLAN_QTY * (IFNULL(CI.TIRE_FABRIC_CRAFT1 * CI.TIRE_FABRIC_LENGTH1, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT2 * CI.TIRE_FABRIC_LENGTH2, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT3 * CI.TIRE_FABRIC_LENGTH3, 0)) / 1000 / 1000 / #{breadth})), 0) CX_CLASS4_PLAN, IFNULL(CEILING(SUM(R.CLASS5_PLAN_QTY * (IFNULL(CI.TIRE_FABRIC_CRAFT1 * CI.TIRE_FABRIC_LENGTH1, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT2 * CI.TIRE_FABRIC_LENGTH2, 0) + IFNULL(CI.TIRE_FABRIC_CRAFT3 * CI.TIRE_FABRIC_LENGTH3, 0)) / 1000 / 1000 / #{breadth})), 0) CX_CLASS5_PLAN, CI.ORIGINAL_LINE_CODE ORIGINAL_LINE_CODE FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IS NOT NULL AND NOT EXISTS ( /*收尾规格不用备*/ SELECT 0 FROM t_xwyy_params p WHERE p.param_code = 'CLOSE_OUT_SPEC_REMARK' AND r.remark = p.param_value )
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
GROUP BY R.SCHEDULE_DATE, R.CX_BATCH_NO, CI.CORD_SPEC, CI.ORIGINAL_LINE_CODE UNION ALL SELECT R.SCHEDULE_DATE, /*排产日期*/ R.CX_BATCH_NO, /*成型批次号*/ 'NC11' BIG_ROLL_CODE, /*冠带条压延物*/ IFNULL(ROUND(SUM(R.CLASS3_PLAN_QTY * CI.CROWN_STRIP_LENGTH / 1000 / 1000 / #{breadth}), 6), 0) DAY_PLAN_QTY, /*中班计划量*/ IFNULL(ROUND(SUM(R.CLASS4_PLAN_QTY * CI.CROWN_STRIP_LENGTH / 1000 / 1000 / #{breadth}), 6), 0) NIGHT_PLAN_QTY, /*夜班计划量*/ IFNULL(CEILING(SUM(R.CLASS3_PLANNED_QTY * CI.CROWN_STRIP_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS1_PLAN, IFNULL(CEILING(SUM(R.CLASS2_PLAN_QTY * CI.CROWN_STRIP_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS2_PLAN, IFNULL(CEILING(SUM(R.CLASS3_PLAN_QTY * CI.CROWN_STRIP_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS3_PLAN, IFNULL(CEILING(SUM(R.CLASS4_PLAN_QTY * CI.CROWN_STRIP_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS4_PLAN, IFNULL(CEILING(SUM(R.CLASS5_PLAN_QTY * CI.CROWN_STRIP_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS5_PLAN, '840D' ORIGINAL_LINE_CODE /*冠带条压延物原丝*/ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IS NOT NULL AND NOT EXISTS ( /*收尾规格不用备*/ SELECT 0 FROM t_xwyy_params p WHERE p.param_code = 'CLOSE_OUT_SPEC_REMARK' AND r.remark = p.param_value )
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
GROUP BY R.SCHEDULE_DATE, R.CX_BATCH_NO ) R GROUP BY SCHEDULE_DATE, CX_BATCH_NO, BIG_ROLL_CODE, ORIGINAL_LINE_CODE HAVING SUM(IFNULL(R.CX_CLASS1_PLAN, 0) + IFNULL(R.CX_CLASS2_PLAN, 0) + IFNULL(R.CX_CLASS3_PLAN, 0) + IFNULL(R.CX_CLASS4_PLAN, 0) + IFNULL(R.CX_CLASS5_PLAN, 0)) != 0

SELECT CI.EMBRYO_CODE, CI.TIRE_FABRIC_LENGTH1 SIDEWALL_LENGTH, CI.CORD_SPEC, CI.TIRE_FABRIC_CODE1, CI.TIRE_FABRIC_CRAFT1, CI.TIRE_FABRIC_CODE2, CI.TIRE_FABRIC_CRAFT2, CI.TIRE_FABRIC_CODE3, CI.TIRE_FABRIC_CRAFT3 FROM T_PRODUCT_CONSTRUCTION_INFO CI WHERE CI.DEL_FLAG = '0'
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
AND EXISTS (SELECT 1 FROM T_CX_SCHEDULE_RESULT R WHERE R.schedule_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION)

WITH temp_tab_BIG_ROLL_CODE AS (
SELECT #{bigRollCode} big_roll_code FROM dual
) SELECT BIG_ROLL_CODE, CEILING(SUM(SINGLE_SHIFT_LH_QTY * 3 * SIDEWALL_LENGTH * TIRE_FABRIC_CRAFT) / #{breadth}) DAY_USED /*日用参考量*/ FROM ( SELECT CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE1 CLOTH_CODE, /*1#胎体布编号*/ IFNULL(R.SINGLE_SHIFT_LH_QTY, 0) SINGLE_SHIFT_LH_QTY, /*单班硫化产量*/ IFNULL(CI.TIRE_FABRIC_LENGTH1 / 1000, 0) SIDEWALL_LENGTH, /*单耗，单位换毫米换算成米*/ IFNULL(CI.TIRE_FABRIC_CRAFT1 / 1000, 0) TIRE_FABRIC_CRAFT /*工艺，单位换毫米换算成米*/ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON CI.EMBRYO_CODE = R.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' /*AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT1), '(^[+-]?\d{0,}\.?\d{0,}$)')*/ /*排除非数字字符串*/ UNION ALL SELECT CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE2 CLOTH_CODE, /*2#胎体布编号*/ IFNULL(R.SINGLE_SHIFT_LH_QTY, 0) SINGLE_SHIFT_LH_QTY, /*单班硫化产量*/ IFNULL(CI.TIRE_FABRIC_LENGTH2 / 1000, 0) SIDEWALL_LENGTH, /*单耗*/ IFNULL(CI.TIRE_FABRIC_CRAFT2 / 1000, 0) TIRE_FABRIC_CRAFT /*工艺*/ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON CI.EMBRYO_CODE = R.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE2 IS NOT NULL /*AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT2), '(^[+-]?\d{0,}\.?\d{0,}$)')*/ UNION ALL SELECT CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE3 CLOTH_CODE, /*3#胎体布编号*/ IFNULL(R.SINGLE_SHIFT_LH_QTY, 0) SINGLE_SHIFT_LH_QTY, /*单班硫化产量*/ (CI.TIRE_FABRIC_LENGTH3 / 1000) SIDEWALL_LENGTH, /*单耗*/ (CI.TIRE_FABRIC_CRAFT3 / 1000) TIRE_FABRIC_CRAFT /*工艺*/ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON CI.EMBRYO_CODE = R.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE3 IS NOT NULL /*AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT3), '(^[+-]?\d{0,}\.?\d{0,}$)')*/ ) t WHERE t.BIG_ROLL_CODE IN ( SELECT big_roll_code FROM temp_tab_BIG_ROLL_CODE ) GROUP BY t.BIG_ROLL_CODE

mapper.update:
    UPDATE T_XWYY_AUTO_SCHEDULE_RECORD
    SET DEL_FLAG  = '1',
        UPDATE_BY = #{createBy},
	       UPDATE_TIME = #{createTime}
	 WHERE schedule_date = #{scheduleDate}
	   AND DEL_FLAG = '0'

mapper.select:
SELECT *
  FROM T_XWYY_SCHEDULE_RESULT t
 WHERE t.SCHEDULE_DATE = #{scheduleDate}

SELECT * FROM t_xwyy_machine_info WHERE del_flag = '0'

	AND ID IN

		#{id}

mapper.update:
UPDATE T_XWYY_SCHEDULE_RESULT as a JOIN (
SELECT #{item.id} AS id, #{item.batchNo} as batch_no, #{item.orderNo} as order_no FROM DUAL
) tempTable ON a.id = tempTable.id SET a.batch_no = tempTable.batch_no, a.order_no = tempTable.order_no where a.del_flag = '0'
